        $$;


--
-- Name: gen_zuid(integer, integer, integer, integer); Type: FUNCTION; Schema: isahl; Owner: -
--

CREATE FUNCTION isahl.gen_zuid(peer_type integer DEFAULT 0, idc integer DEFAULT 0, cluster integer DEFAULT 0, node integer DEFAULT 0) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    ZUID_EPOCH CONSTANT BIGINT := 1622505600000;
    TYPE_SHIFT CONSTANT INTEGER := 24;
    IDC_SHIFT CONSTANT INTEGER := 21;
    CLUSTER_SHIFT CONSTANT INTEGER := 18;
    NODE_SHIFT CONSTANT INTEGER := 13;
    TIMESTAMP_SHIFT CONSTANT INTEGER := 11;
    TYPE_MASK CONSTANT BIGINT := 3;
    IDC_MASK CONSTANT BIGINT := 7;
    CLUSTER_MASK CONSTANT BIGINT := 7;
    NODE_MASK CONSTANT BIGINT := 31;
    TIMESTAMP_MASK CONSTANT BIGINT := 1099511627775;
    SEQUENCE_MASK CONSTANT BIGINT := 2047;
    now_ms BIGINT;
    seq BIGINT;
    result BIGINT;
BEGIN
    IF peer_type < 0 OR peer_type > TYPE_MASK THEN
        RAISE EXCEPTION 'Invalid peer_type: %. Must be 0-3', peer_type;
    END IF;
    IF idc < 0 OR idc > IDC_MASK THEN
        RAISE EXCEPTION 'Invalid idc: %. Must be 0-7', idc;
    END IF;
    IF cluster < 0 OR cluster > CLUSTER_MASK THEN
        RAISE EXCEPTION 'Invalid cluster: %. Must be 0-7', cluster;
    END IF;
    IF node < 0 OR node > NODE_MASK THEN
        RAISE EXCEPTION 'Invalid node: %. Must be 0-31', node;
    END IF;
    now_ms := (EXTRACT(EPOCH FROM clock_timestamp()) * 1000)::BIGINT - ZUID_EPOCH;
    now_ms := now_ms & TIMESTAMP_MASK;
    seq := nextval('isahl.zuid_seq') & SEQUENCE_MASK;
    result := ((peer_type::BIGINT & TYPE_MASK) << TYPE_SHIFT) |
              ((idc::BIGINT & IDC_MASK) << IDC_SHIFT) |
              ((cluster::BIGINT & CLUSTER_MASK) << CLUSTER_SHIFT) |
              ((node::BIGINT & NODE_MASK) << NODE_SHIFT) |
              (now_ms << TIMESTAMP_SHIFT) |
              seq;
    RETURN result;
END;
$$;


--
-- Name: get_logistics_task_related_ops(bigint); Type: FUNCTION; Schema: isahl; Owner: -
--

CREATE FUNCTION isahl.get_logistics_task_related_ops(p_task_id bigint) RETURNS TABLE(source text, entity_id bigint, entity_code text, entity_notice text, entity_type text, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
    -- 关联 transport operations（通过 fk_subject 匹配 operation.id）
    SELECT
        'transport'::TEXT AS source,
        op.id AS entity_id,
        op.code AS entity_code,
        op.notice AS entity_notice,
        op."biz-type" AS entity_type,
        op.created_at
    FROM isahl.zc_id_task t
    JOIN isahl.zc_id_operation op ON op.id = t.fk_subject
    WHERE t.id = p_task_id AND t.deleted_at IS NULL AND op.deleted_at IS NULL

    UNION ALL

    -- 关联 inventory stock_in（通过 fk_subject 匹配 stock_in.id）
    SELECT
        'inventory_in'::TEXT,
        si.id,
        si.code,
        si.notice,
        'stock_in'::TEXT,
        si.created_at
    FROM isahl.zc_id_task t
    JOIN isahl."zc_id_oper-put_in_stock" si ON si.id = t.fk_subject
    WHERE t.id = p_task_id AND t.deleted_at IS NULL AND si.deleted_at IS NULL

    UNION ALL

    -- 关联 inventory stock_out（通过 fk_subject 匹配 stock_out.id）
    SELECT
        'inventory_out'::TEXT,
        so.id,
        so.code,
        so.notice,
        'stock_out'::TEXT,
        so.created_at
    FROM isahl.zc_id_task t
    JOIN isahl."zc_id_oper-take_off_stock" so ON so.id = t.fk_subject
    WHERE t.id = p_task_id AND t.deleted_at IS NULL AND so.deleted_at IS NULL;
$$;


--
-- Name: get_logistics_task_summary(); Type: FUNCTION; Schema: isahl; Owner: -
--

CREATE FUNCTION isahl.get_logistics_task_summary() RETURNS TABLE(biz_type text, task_count bigint, latest_created_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
    SELECT
        COALESCE(t."biz-type", 'unknown') AS biz_type,
        COUNT(*) AS task_count,
        MAX(t.created_at) AS latest_created_at
    FROM isahl.zc_id_task t
    WHERE t.deleted_at IS NULL
    GROUP BY t."biz-type"
    ORDER BY task_count DESC;
$$;


--
-- Name: get_object_reachable_oa(bigint); Type: FUNCTION; Schema: isahl; Owner: -
--

CREATE FUNCTION isahl.get_object_reachable_oa(p_oa_id bigint) RETURNS TABLE(oa_id bigint, depth integer)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    WITH RECURSIVE reachable AS (
        -- Base case: the object itself
        SELECT p_oa_id AS oa_id, 0 AS depth

        UNION

        -- Recursive case: parent attributes (up the hierarchy)
        SELECT unnest(oa.ancestor_ids) AS oa_id, r.depth + 1
        FROM isahl_auth.ngac_object_attribute oa
        JOIN reachable r ON oa.id = r.oa_id
        WHERE r.depth < 100  -- Prevent infinite loops
    )
    SELECT DISTINCT r.oa_id, MIN(r.depth) AS depth
    FROM reachable r
    GROUP BY r.oa_id;
END;
$$;


--
-- Name: get_user_reachable_ua(bigint); Type: FUNCTION; Schema: isahl; Owner: -
--

CREATE FUNCTION isahl.get_user_reachable_ua(p_user_id bigint) RETURNS TABLE(ua_id bigint, depth integer)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    WITH RECURSIVE reachable AS (
        -- Base case: directly assigned attributes
        SELECT uaa.fk_user_attribute AS ua_id, 0 AS depth
        FROM isahl_auth.ngac_user_rr_attribute uaa
        WHERE uaa.fk_user = p_user_id
            AND (uaa.expires_at IS NULL OR uaa.expires_at > NOW())

        UNION

        -- Recursive case: parent attributes (up the hierarchy)
        SELECT unnest(ua.ancestor_ids) AS ua_id, r.depth + 1
        FROM isahl_auth.ngac_user_attribute ua
        JOIN reachable r ON ua.id = r.ua_id
        WHERE r.depth < 100  -- Prevent infinite loops
    )
    SELECT DISTINCT r.ua_id, MIN(r.depth) AS depth
    FROM reachable r
    GROUP BY r.ua_id;
END;
$$;


--
-- Name: gf_check_gen_next_uid_uniqueness(); Type: FUNCTION; Schema: isahl; Owner: -
--

CREATE FUNCTION isahl.gf_check_gen_next_uid_uniqueness() RETURNS TABLE(table_name name, schema_name name, table_code bigint, default_expr text, is_duplicate boolean, conflict_count bigint, missing_default boolean)
    LANGUAGE plpgsql STABLE
    AS $$
        BEGIN
            RETURN QUERY
            WITH RECURSIVE
            uid_defaults AS (
                SELECT
                    c.relname::name AS table_name,
                    n.nspname::name AS schema_name,
                    -- gen_next_uid 内部将 code 截断为 16 位（& 65535），
                    -- 唯一性检测必须按掩码后值比较，否则同余字面值逃逸检测
                    (substring(pg_get_expr(d.adbin, d.adrelid)
                        FROM 'gen_next_uid\((?:\(?)([0-9]+)(?:\)?::bigint)?\)')::bigint & 65535) AS table_code,
                    pg_get_expr(d.adbin, d.adrelid)::text AS default_expr
                FROM pg_class c
                JOIN pg_namespace n ON n.oid = c.relnamespace
                JOIN pg_attrdef d ON d.adrelid = c.oid
                    AND d.adnum = (
                        SELECT a.attnum FROM pg_attribute a
                        WHERE a.attrelid = c.oid AND a.attname = 'id'
                    )
                WHERE c.relkind = 'r'
                  -- 元数据异常检测仅纳入 isahl.* 本体 schema（批注闭环：wz_fssc 等业务 schema 泄漏为 UID 冲突误报）
                  AND n.nspname = 'isahl'
                  AND pg_get_expr(d.adbin, d.adrelid) LIKE '%gen_next_uid(%'
            ),
            code_counts AS (
                SELECT u.table_code, COUNT(*) AS cnt
                FROM uid_defaults u
                WHERE u.table_code IS NOT NULL
                GROUP BY u.table_code
            ),
            gen_uid AS (
                SELECT
                    u.table_name, u.schema_name, u.table_code,
                    u.default_expr,
                    (c.cnt > 1) AS is_duplicate,
                    c.cnt AS conflict_count,
                    false::boolean AS missing_default
                FROM uid_defaults u
                LEFT JOIN code_counts c ON c.table_code = u.table_code
            ),
            inherit_all AS (
                SELECT c.oid AS leaf_oid, c.oid AS node_oid, c.relname AS leaf_name
                FROM pg_class c
                JOIN pg_namespace n ON n.oid = c.relnamespace
                WHERE n.nspname = 'isahl' AND c.relkind = 'r'
                UNION ALL
                SELECT ic.leaf_oid, i.inhparent AS node_oid, ic.leaf_name
                FROM inherit_all ic
                JOIN pg_inherits i ON i.inhrelid = ic.node_oid
            ),
            no_default AS (
                SELECT DISTINCT leaf_name
                FROM inherit_all ic
                WHERE NOT EXISTS (
                    SELECT 1 FROM pg_attrdef d
                    JOIN pg_attribute a ON a.attrelid = d.adrelid AND a.attnum = d.adnum
                    WHERE d.adrelid = ic.node_oid AND a.attname = 'id'
                )
            ),
            missing_id AS (
                SELECT
                    m.leaf_name::name AS table_name,
                    'isahl'::name AS schema_name,
                    0::bigint AS table_code,
                    ''::text AS default_expr,
                    false::boolean AS is_duplicate,
                    0::bigint AS conflict_count,
                    true::boolean AS missing_default
                FROM no_default m
            )
            SELECT * FROM gen_uid
            UNION ALL
            SELECT * FROM missing_id
            ORDER BY conflict_count DESC, table_code, table_name;
        END;
        $$;


--
-- Name: gf_clean_contacts(); Type: FUNCTION; Schema: isahl; Owner: -
--

CREATE FUNCTION isahl.gf_clean_contacts(OUT dc integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
    WITH dcc AS (
        DELETE FROM isahl.zc_id_contacts RETURNING id
    ),
    ci AS (
        DELETE FROM isahl.zc_id_contacts_rr_infos
        WHERE ref_left = ANY(SELECT ref_right FROM dcc)
        RETURNING id
    )
    SELECT count(*) FROM ci INTO dc;
END;
$$;


--
-- Name: gf_clean_entity(); Type: FUNCTION; Schema: isahl; Owner: -
--

CREATE FUNCTION isahl.gf_clean_entity(OUT rc integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
	did bigint;
BEGIN
	rc := 0;
	FOR did IN DELETE FROM isahl.zc_id_entity WHERE NOT o_name = ANY('{银行-中央银行,主体-国家/地区,主体-超国家实体}') RETURNING id LOOP
		WITH df AS (DELETE FROM isahl."zc_id_subjects_rr_storage" WHERE ref_left = did RETURNING ref_right)
		DELETE FROM isahl.zc_id_storage WHERE id = ANY(SELECT ref_right FROM df);
		DELETE FROM isahl."zc_id_subj-post_rr_employee" WHERE ref_right = did;
		DELETE FROM isahl."zc_id_subj-org_rr_subordinate" WHERE ref_left = did OR ref_right = did;
		DELETE FROM isahl."zc_id_subj-org_rr_position" WHERE ref_left = did;
		DELETE FROM isahl."zc_id_subj-org_rr_sharehold" WHERE ref_left = did OR ref_right = did;
		DELETE FROM isahl."zc_id_subj-org_rr_member" WHERE ref_left = did OR ref_right = did;
		DELETE FROM isahl."zc_id_subj-org_rr_employee" WHERE ref_left = did OR ref_right = did;
		DELETE FROM isahl."zc_id_subj-employee_r_employ-status" WHERE ref_left = did;
		DELETE FROM isahl."zc_id_subj-group_rr_member" WHERE ref_left = did OR ref_right = did;
		DELETE FROM isahl."zc_id_subj-group_rr_project" WHERE ref_left = did;
		DELETE FROM isahl."zc_id_order_rr_subj-rep" WHERE ref_right = did;
		DELETE FROM isahl."zc_id_order_rr_obj-rep" WHERE ref_right = did;
		WITH df AS (DELETE FROM isahl."zc_id_entity_rr_identity" WHERE ref_left = did RETURNING ref_right)
		DELETE FROM isahl.zc_id_identity WHERE id = ANY (SELECT ref_right FROM df);
		WITH df AS (DELETE FROM isahl."zc_id_entity_rr_contacts" WHERE ref_left = did RETURNING ref_right),
        dc AS (DELETE FROM isahl.zc_id_contacts WHERE id = ANY (SELECT ref_right FROM df) RETURNING id),
		di AS (DELETE FROM isahl.zc_id_contacts_rr_infos WHERE ref_left = ANY (SELECT id FROM dc) RETURNING ref_right)
		DELETE FROM isahl.zc_id_contact_infos WHERE id = ANY (SELECT ref_right FROM di);
		DELETE FROM isahl."zc_id_empl-natural_rr_country" WHERE ref_left = did;
		DELETE FROM isahl."zc_id_even-modify_rr_rev-group" WHERE ref_right = did;
		DELETE FROM isahl."zc_id_approve_rr_rev-group" WHERE ref_right = did;
		DELETE FROM isahl."zc_id_approve_rr_act-group" WHERE ref_right = did;
		DELETE FROM isahl."zc_id_prod-proxy_rr_principal" WHERE ref_right = did;
		DELETE FROM isahl."zc_id_plan_rr_participants" WHERE ref_right = did;
		DELETE FROM isahl.zc_id_storage WHERE fk_trustee = did OR fk_trustee IS NULL;
		rc := rc + 1;
	END LOOP;
END;
$$;


--
-- Name: gf_clean_evaluation(); Type: FUNCTION; Schema: isahl; Owner: -
--

CREATE FUNCTION isahl.gf_clean_evaluation(OUT rc integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
    WITH to_delete AS (
        SELECT e.id
        FROM isahl.zc_id_evaluation e
        WHERE COALESCE(e.ref_count, 0) = 0
          -- m2n junction 引用不在 ref_count 维护范围内，被引用的评估值不可清理
          AND NOT EXISTS (SELECT 1 FROM isahl."zc_id_plan_rr_task" j WHERE j.ref_right = e.id)
          AND NOT EXISTS (SELECT 1 FROM isahl."zc_id_project_rr_task" j WHERE j.ref_right = e.id)
          AND NOT EXISTS (SELECT 1 FROM isahl."zc_id_subjects_rr_container" j WHERE j.ref_right = e.id)
    ), del AS (
        DELETE FROM isahl.zc_id_evaluation
        WHERE id IN (SELECT id FROM to_delete)
        RETURNING id
    )
    SELECT count(*) INTO rc FROM del;
END;
$$;


