--
-- Name: gf_uid_table_order(); Type: FUNCTION; Schema: isahl; Owner: -
--

CREATE FUNCTION isahl.gf_uid_table_order() RETURNS TABLE(table_name name, max_depth bigint, is_lifecycle boolean, order_seq bigint)
    LANGUAGE sql STABLE
    AS $$
  WITH RECURSIVE
  inh_all AS (
    SELECT c.oid, c.relname::name AS table_name, 0::bigint AS depth
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'isahl' AND c.relkind = 'r' AND c.relispartition = false
      AND NOT EXISTS (SELECT 1 FROM pg_inherits WHERE inhrelid = c.oid)
    UNION ALL
    SELECT c.oid, c.relname::name, ia.depth + 1
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    JOIN pg_inherits i ON i.inhrelid = c.oid
    JOIN inh_all ia ON ia.oid = i.inhparent
    WHERE n.nspname = 'isahl' AND c.relkind = 'r' AND c.relispartition = false
  ),

  lifecycle AS (
    SELECT c.oid
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'isahl' AND c.relname = 'zc_id_lifecycle'
    UNION ALL
    SELECT c.oid
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    JOIN pg_inherits i ON i.inhrelid = c.oid
    JOIN lifecycle lc ON lc.oid = i.inhparent
    WHERE n.nspname = 'isahl' AND c.relkind = 'r' AND c.relispartition = false
  )
  SELECT
    ia.table_name,
    MAX(ia.depth)::bigint AS max_depth,
    bool_or(lc.oid IS NOT NULL) AS is_lifecycle,
    row_number() OVER (ORDER BY MAX(ia.depth), ia.table_name)::bigint AS order_seq
  FROM inh_all ia
  LEFT JOIN lifecycle lc ON lc.oid = ia.oid
  GROUP BY ia.table_name
  ORDER BY MAX(ia.depth), ia.table_name;
$$;


--
-- Name: tf_clear_place_fence_ref(); Type: FUNCTION; Schema: isahl; Owner: -
--

CREATE FUNCTION isahl.tf_clear_place_fence_ref() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN
        UPDATE isahl."zc_id_place" SET qk_fence = NULL WHERE qk_fence = OLD.id;
    END IF;
    RETURN NEW;
END;
$$;


