--
-- Name: mv_inventory; Type: MATERIALIZED VIEW; Schema: isahl; Owner: -
--

CREATE MATERIALIZED VIEW isahl.mv_inventory AS
 SELECT r.id,
    r.ref_left AS production_id,
    r.ref_right AS storage_id,
    COALESCE(sm.mark, (0)::numeric) AS qty,
    COALESCE(cap.mark, (0)::numeric) AS capacity,
    r.sk_unit AS unit,
    cnt.counted_mark AS last_counted_qty,
    (cnt.counted_mark - COALESCE(sm.mark, (0)::numeric)) AS variance,
    r.created_at,
    r.updated_at
   FROM ((((isahl.zc_id_production_rr_storage r
     LEFT JOIN isahl."zc_id_scal-common" sm ON ((sm.id = r.qk_qty)))
     LEFT JOIN isahl."zc_id_scal-common" cap ON ((cap.id = r.qk_p_capacity)))
     LEFT JOIN isahl."zc_id_segm-date" pd ON ((pd.id = r.qk_period)))
     LEFT JOIN LATERAL ( SELECT sc.mark AS counted_mark
           FROM ((isahl."zc_id_deta-counting" d
             LEFT JOIN isahl."zc_id_scal-common" sc ON ((sc.id = d.qk_qty)))
             LEFT JOIN isahl."zc_id_scal-date" sd ON ((sd.id = d.qk_date)))
          WHERE ((d.fk_production = r.ref_left) AND (d.fk_storage = r.ref_right) AND (d.deleted_at IS NULL))
          ORDER BY sd.date DESC NULLS LAST, d.id DESC
         LIMIT 1) cnt ON (true))
  WHERE ((r.deleted_at IS NULL) AND ((r.qk_period IS NULL) OR (pd.date_st IS NULL) OR (pd.date_ed IS NULL) OR ((now() >= pd.date_st) AND (now() <= pd.date_ed))))
  WITH NO DATA;


